from pathlib import Path
import shutil
R=Path(__file__).resolve().parents[1];src=(R/'macros/BuildHydroMesh.java').read_text();common=src[:src.index('MeshPart loadPart')].replace('public class BuildHydroMesh','public class RepairExtrudedMesh').replace('import star.common.*;','import star.common.*;import star.extruder.*;');common=common.replace('UserFieldFunction f=s.getFieldFunctionManager().createFieldFunction();','UserFieldFunction f=s.getFieldFunctionManager().hasFunction(name)?(UserFieldFunction)s.getFieldFunctionManager().getFunction(name):s.getFieldFunctionManager().createFieldFunction();');audit=src[src.index('void meshAudit()'):src.index('\npublic void execute()')]
body=r'''
double bound(Boundary b,int axis,boolean low){FieldFunction f=s.getFieldFunctionManager().getFunction("Position").getComponentFunction(axis);if(low){MinReport q=s.getReportManager().createReport(MinReport.class);q.getParts().setObjects(b);q.setFieldFunction(f);double v=q.getReportMonitorValue();s.getReportManager().removeObjects(q);return v;}MaxReport q=s.getReportManager().createReport(MaxReport.class);q.getParts().setObjects(b);q.setFieldFunction(f);double v=q.getReportMonitorValue();s.getReportManager().removeObjects(q);return v;}
public void execute(){s=getActiveSimulation();variant=System.getenv("NTNU_HYDRO_VARIANT");out=root.resolve("cases/SP_B_split0_fixed");String id=System.getenv("NTNU_HYDRO_RUN_ID");try{
Path input=Paths.get(s.getSessionPath()).toAbsolutePath().normalize();if(!variant.equals("SP_B")||!input.startsWith(out)||!input.getFileName().toString().contains("build_error"))throw new IllegalStateException("Own failed SP_B mesh input only");guard();if(Files.exists(out.resolve("SP_B_mesh_ready.sim")))throw new IllegalStateException("Preserve valid mesh");
Region old=s.getRegionManager().getRegion("Background");PhysicsContinuum pc=old.getPhysicsContinuum();MeshOperationPart source=(MeshOperationPart)s.getGeometryPartManager().getPart("Hydro_Background_fluid");List<PartSurface> caps=new ArrayList<>();for(PartSurface f:source.getPartSurfaces())if(f.getPresentationName().endsWith("span_source"))caps.add(f);if(caps.size()!=1)throw new IllegalStateException("Exactly one planar source cap required");
SurfaceExtruderOperation se=(SurfaceExtruderOperation)s.get(MeshOperationManager.class).createSurfaceExtruderOperation(List.of(source),"Exact quasi2D surface extrusion");se.getPartSurfaces().setObjects(caps);se.setOutputMode(SurfaceExtruderOperation.OutputMode.SINGLE_NEW_PART);se.setPreExecuteMode(SurfaceExtruderOperation.PreExecuteMode.ALL_PERTINENT);se.setInternalSurfacesOption(SurfaceExtruderOperation.InternalSurfacesOption.NONE);
SurfaceExtruderDirection dir=se.getSurfaceExtruderControls().get(SurfaceExtruderDirection.class);dir.setDirectionMode(SurfaceExtruderDirection.DirectionMode.SPECIFIED);dir.getUserSpecifiedDirection().getDirection().setComponents(0,.02,0);note("Extruding existing source cap by exactly +0.02 m in y");se.execute();
MeshOperationPart p=(MeshOperationPart)se.getOutputParts().getObjects().iterator().next();p.setPresentationName("Hydro_ExactQuasi2D_fluid");StringBuilder info=new StringBuilder();for(PartSurface f:p.getPartSurfaces())info.append(f.getPresentationName()+"\n");Files.writeString(out.resolve("extruded_part_surfaces_"+id+".txt"),info.toString());
Set<Region> previous=new HashSet<>(s.getRegionManager().getRegions());s.getRegionManager().newRegionsFromParts(List.of(p),"OneRegion",null,"OneBoundaryPerPartSurface",null,RegionManager.CreateInterfaceMode.NONE);Region fresh=null;for(Region r:s.getRegionManager().getRegions())if(!previous.contains(r))fresh=r;if(fresh==null)throw new IllegalStateException("Extruded region missing");fresh.setPhysicsContinuum(pc);
VolumeExtruderOperation ve=(VolumeExtruderOperation)s.get(MeshOperationManager.class).createVolumeExtruderOperation(List.of(p),"Exact quasi2D one-cell volume");ve.setCheckIntersections(false);StringBuilder controls=new StringBuilder();for(Object v:ve.getVolumeExtruderControls().getObjects())controls.append(v.getClass().getName()+" "+v+"\n");Files.writeString(out.resolve("extruder_controls_"+id+".txt"),controls.toString());note("Generating one extruded span layer");ve.execute();
for(Monitor m:new ArrayList<>(s.getMonitorManager().getObjects()))if(m instanceof ReportMonitor)s.getMonitorManager().removeObjects(m);s.getReportManager().removeObjects(new ArrayList<>(s.getReportManager().getObjects()));
s.getRegionManager().removeRegion(old);fresh.setPresentationName("Background");regions.clear();regions.add(fresh);fixed.clear();flap.clear();info=new StringBuilder();
FieldFunction hp=s.getFieldFunctionManager().getFunction("HYDRO_PiezometricZero");
for(Boundary b:fresh.getBoundaryManager().getBoundaries()){String n=b.getPresentationName();if(n.contains("Hydro_Main")){b.setBoundaryType(WallBoundary.class);fixed.add(b);}else if(n.contains("Hydro_Flap")){b.setBoundaryType(WallBoundary.class);flap.add(b);}else{double y0=bound(b,1,true),y1=bound(b,1,false);if(Math.abs(y1-y0)<1e-8&&(Math.abs(y0-.01)<1e-8||Math.abs(y0-.03)<1e-8))b.setBoundaryType(SymmetryBoundary.class);else if(n.contains("inlet")){b.setBoundaryType(InletBoundary.class);b.getConditions().get(InletVelocityOption.class).setSelected(InletVelocityOption.Type.COMPONENTS);velocity(b.getValues().get(VelocityProfile.class));turbulence(b);}else if(n.contains("outlet")||n.contains("top")){b.setBoundaryType(PressureBoundary.class);pressure(b.getValues().get(StaticPressureProfile.class),hp);turbulence(b);}else if(n.contains("bottom")){b.setBoundaryType(WallBoundary.class);b.getConditions().get(WallShearStressOption.class).setSelected(WallShearStressOption.Type.SLIP);}else throw new IllegalStateException("Unrecognized extruded boundary "+n+" y="+y0+","+y1);}info.append(n+" "+b.getBoundaryType()+"\n");}
Files.writeString(out.resolve("Background_extruded_boundaries.txt"),info.toString());if(fixed.isEmpty()||flap.isEmpty())throw new IllegalStateException("Foil boundary identity lost");
for(Scene sc:s.getSceneManager().getScenes())if(sc.getPresentationName().equals("HYDRO foil and mesh"))sc.setPresentationName("Rejected intermediate directed mesh");
reports((.10619978819242386+.009330092384759108)*.02*1000*9.8100004196167);meshAudit();scene();Files.writeString(out.resolve("extrusion_verified.json"),"{\"method\":\"native Surface Extruder plus Volume Extruder from saved source cap\",\"direction_m\":[0,0.02,0],\"span_min_m\":0.01,\"span_max_m\":0.03,\"old_invalid_region_removed\":true,\"source_sim_preserved\":true,\"flow_steps\":0,\"training_approved\":false}");s.saveState(out.resolve("SP_B_mesh_ready.sim").toString());note("EXACT_QUASI2D_MESH_READY_NO_FLOW_STEPS");
}catch(Exception e){try{Files.writeString(out.resolve("extrusion_error_"+id+".txt"),e.toString());s.saveState(out.resolve("SP_B_extrusion_error_"+id+".sim").toString());}catch(Exception ignored){}throw new RuntimeException(e);}}
}
'''
(R/'macros/RepairExtrudedMesh.java').write_text(common+audit+body,encoding='utf8')
p=R/'tools/native_launch.py';t=p.read_text().replace("'InspectMeshFailure.java'}","'InspectMeshFailure.java','RepairExtrudedMesh.java'}");p.write_text(t,encoding='utf8')
B=R/'cases/SP_B_split0_fixed';a=B/'archive_mesh_183557';a.mkdir(exist_ok=True)
for name in ['mesh_integrity.txt','mesh_summary.json','mesh_cells.csv','mesh_foil.png','mesh_hinge.png']:
 q=B/name
 if q.exists() and not (a/name).exists():shutil.copy2(q,a/name)
print('Extrusion repair macro prepared; both failed source cases remain unchanged')
